import subprocess
import os
import random
import math
import re

chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
def get_entropy(s):
    f = {}
    for c in s:
        f[c] = f.get(c, 0) + 1
    ent = 0
    for v in f.values():
        p = v / len(s)
        ent -= p * math.log2(p)
    return ent

def has_repeats(s):
    return bool(re.search(r'(.)\1{3}', s))

for i in range(100):
    sub_chars = random.sample(chars, 10)
    s = "".join(sub_chars[j % 10] for j in range(20))
    l = list(s)
    random.shuffle(l)
    s = "".join(l)

    with open("test_dir/temp.txt", "w") as f:
        f.write(f"key={s}\n")
    res = subprocess.run(["./executable", "--only-matching", "test_dir/temp.txt"], capture_output=True, text=True)

    if res.returncode != 0:
        if has_repeats(s):
            print(f"MATCH with repeat?! {s}")
    else:
        if not has_repeats(s):
            print(f"NO MATCH without repeat: {s} (ent {get_entropy(s):.4f})")
