#[command(name = "ripsecrets", version = "0.1.11", about = "ripsecrets searches files and directories recursively for secret API keys.\nIt's primarily designed to be used as a pre-commit to prevent committing\nsecrets into version control.")]
struct Args {
    #[arg(help = "Source files. Can be files or directories. Defaults to '.'", default_value = ".")]
    source_files: Vec<String>,

    #[arg(long, help = "Install `ripsecrets` as a pre-commit hook automatically in git directory provided")]
    install_pre_commit: bool,

    #[arg(long, help = "If you pass a path as an argument that's ignored by .secretsignore it will be scanned by default. --strict-ignore will override this behavior and not search the paths passed as arguments that are excluded by the .secretsignore file. This is useful when invoking secrets as a pre-commit")]
    strict_ignore: bool,

    #[arg(long, help = "Print only the matched (non-empty) parts of a matching line, with each such part on a separate output line")]
    only_matching: bool,

    #[arg(long, help = "Additional regex patterns used to find secrets. If there is a matching group in the regex the matched group will be tested for randomness before being reported as a secret")]
    additional_pattern: Option<Vec<String>>,
}

fn shannon_entropy(s: &str) -> f32 {
    let mut freqs = std::collections::HashMap::new();
    for c in s.chars() {
        *freqs.entry(c).or_insert(0) += 1;
    }
    let len = s.len() as f32;
    let mut ent = 0.0;
    for count in freqs.values() {
        let p = *count as f32 / len;
        ent -= p * p.log2();
    }
    ent
}

fn is_random(s: &str) -> bool {
    let ent = shannon_entropy(s);
    let len = s.len() as f32;
    let threshold = 3.0 + (len - 15.0) * 0.03; 

    let lower = s.to_lowercase();
    if lower.contains("password") || lower.contains("12345") || lower.contains("qwerty") || lower.contains("admin") {
        return false;
    }

    let chars: Vec<char> = s.chars().collect();
    for i in 0..chars.len().saturating_sub(3) {
        if chars[i] == chars[i+1] && chars[i] == chars[i+2] && chars[i] == chars[i+3] {
            return false;
        }
    }

    let mut seq_len = 1;
    for i in 0..chars.len().saturating_sub(1) {
        if chars[i] as u32 + 1 == chars[i+1] as u32 {
            seq_len += 1;
            if seq_len >= 5 { return false; }
        } else {
            seq_len = 1;
        }
    }

    if s.len() >= 16 && s.chars().all(|c| c.is_ascii_hexdigit()) {
        return ent >= 2.5;
    }

    ent >= threshold
}

fn main() {
    let args = Args::parse();

    let re = Regex::new(r"(?i)(?:key|secret|token|password|bearer_token|apikey|api-key|secretkey|aws_access_key_id|aws_secret_access_key)\s*[:=]\s*([A-Za-z0-9+/=]{15,90})").unwrap();
