                                    if args.only_matching {
                                        println!("{}:{}:{}", entry.path().display(), i + 1, secret);
                                    } else {
                                        println!("{}:{}:{}", entry.path().display(), i + 1, line);
                                    }
                                    found = true;
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    if found {
        std::process::exit(1);
    }
}
